def classify_complexity(query):
    # classify the query as simple, moderate, or complex
    words = query.lower().split()
    if len(words) <= 3 and "and" not in words:
        return "simple"
    if " and " in query.lower() or "compare" in query.lower():
        return "complex"
    return "moderate"

def skip_retrieval_strategy(query):
    # skip retrieval for simple queries
    return f"Answered directly, no retrieval: {query}"

def single_pass_strategy(query):
    # use a single retrieval pass for moderate queries
    return f"Retrieved once, then answered: {query}"

def multi_step_strategy(query):
    # decompose and retrieve multiple times for complex queries
    return f"Decomposed and retrieved multiple times, then answered: {query}"

def adaptive_rag(query):
    complexity = classify_complexity(query)
    strategy = {
        "simple": skip_retrieval_strategy,
        "moderate": single_pass_strategy,
        "complex": multi_step_strategy,
    }[complexity]
    return complexity, strategy(query)

queries = [
    "what time is it",
    "What does the Falcon plan cost?",
    "Compare the Falcon plan and the Eagle plan and explain the difference",
]

for q in queries:
    complexity, result = adaptive_rag(q)
    print(f"Query: {q}")
    print(f"Classified as: {complexity}")
    print(f"Result: {result}\n")
